result:
Ya tengo todo lo necesario: `policy` es `SettingsJson | null` y el esquema (`settings/types.ts`) no declara `allowedChannelPlugins`/`channelsEnabled` (confirmado en `settings/inventory.ts`), así que el `.passthrough()` de zod lo tipa `unknown`. Propongo validar su forma en el propio archivo antes de pasarlo a `getEffectiveChannelAllowlist`, sin tocar el esquema.

```json
{"file": "src/packages/repl/src/components/LogoV2/ChannelsNotice.tsx",
 "edits": [
   {"old": "import { isChannelsEnabled } from '@thyrox/mcp-runtime/channelAllowlist.js'",
    "new": "import {
  type ChannelAllowlistEntry,
  isChannelsEnabled,
} from '@thyrox/mcp-runtime/channelAllowlist.js'"},
   {"old": "      const allowlist = getEffectiveChannelAllowlist(
        sub,
        policy?.allowedChannelPlugins,
      )",
    "new": "      const allowlist = getEffectiveChannelAllowlist(
        sub,
        toChannelAllowlistEntries(policy?.allowedChannelPlugins),
      )"},
   {"old": "function formatEntry(c: ChannelEntry): string {
  return c.kind === 'plugin'
    ? `plugin:${c.name}@${c.marketplace}`
    : `server:${c.name}`
}

type Unmatched = { entry: ChannelEntry; why: string }",
    "new": "function formatEntry(c: ChannelEntry): string {
  return c.kind === 'plugin'
    ? `plugin:${c.name}@${c.marketplace}`
    : `server:${c.name}`
}

/**
 * `policy` es `SettingsJson | null` y el esquema no declara
 * `allowedChannelPlugins` (ver `settings/inventory.ts`): el acceso cae en el
 * `.passthrough()` de zod y llega como `unknown`. Se valida su forma en vez
 * de asumirla, igual que `getChannelAllowlist` valida el ledger de
 * GrowthBook — si algún elemento no calza, se trata como ausente y se cae
 * al ledger.
 */
function toChannelAllowlistEntries(
  value: unknown,
): ChannelAllowlistEntry[] | undefined {
  if (!Array.isArray(value)) return undefined
  const entries: ChannelAllowlistEntry[] = []
  for (const entry of value) {
    if (typeof entry !== 'object' || entry === null) return undefined
    const e = entry as { marketplace?: unknown; plugin?: unknown }
    if (typeof e.marketplace !== 'string' || typeof e.plugin !== 'string') {
      return undefined
    }
    entries.push({ marketplace: e.marketplace, plugin: e.plugin })
  }
  return entries
}

type Unmatched = { entry: ChannelEntry; why: string }"}
